@layer components {
  .ew-table {
    /* anatomy: root */
  }
  .ew-table { width: 100%; max-width: 100%; border-collapse: collapse; font: inherit; }
  .ew-table caption { text-align: start; font-weight: 700; padding: 8px 0; }
  .ew-table th, .ew-table td { min-width: 0; padding: 8px; text-align: start; border-bottom: 1px solid var(--ew-color-border-subtle); overflow-wrap: anywhere; }
  .ew-table th { font-weight: 700; }
  .ew-table th[aria-sort] { cursor: pointer; }
  .ew-table th[aria-sort="ascending"]::after { content: " \2191"; }
  .ew-table th[aria-sort="descending"]::after { content: " \2193"; }
  .ew-table[data-zebra="true"] tbody tr:nth-child(even) { background: color-mix(in oklch, var(--ew-color-fg-default) 5%, transparent); }
  .ew-table-scroll { max-width: 100%; overflow-x: auto; }
  @media (max-width: 600px) {
    .ew-table[data-responsive="stack"] thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
    .ew-table[data-responsive="stack"] tr { display: grid; border-bottom: 1px solid var(--ew-color-border-subtle); }
    .ew-table[data-responsive="stack"] td { display: grid; grid-template-columns: minmax(0, 8rem) minmax(0, 1fr); border: 0; }
    .ew-table[data-responsive="stack"] td::before { content: attr(data-label); font-weight: 700; }
  }
  /* spec variant variant=default */
  .ew-table[data-variant="default"] { --ew-spec-variant-variant: default; }
  .ew-table:not([data-variant]) { --ew-spec-variant-variant: default; }
  .ew-table[data-size="sm"] { --ew-spec-size: sm; }
  .ew-table[data-size="md"] { --ew-spec-size: md; }
  .ew-table:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-table, .ew-table *, .ew-table *::before, .ew-table *::after {
      transition: none !important;
      animation: none !important;
    }
  }
}
